#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — issue #13 / Ticket 4: provisión de entornos dev y prod.
# Corre desde la raíz del repo (usa rutas relativas a apps/web/ y depende de
# `gh` autenticado contra jab16jy/inventory-tally para los secrets).
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10

banner "Provisión de entornos Firebase — dev y prod"

# ── Dev ─────────────────────────────────────────────────────────────────

stage "Proyecto Firebase — dev"
say "Si el proyecto de dev ya existe, sólo confirma para seguir."
open_url "https://console.firebase.google.com/"
step "Add project → nombre sugerido 'Sistema inventario dev' → Analytics opcional."
note "El project_id que Firebase asigne puede no coincidir con el nombre — no importa, nada en este script asume un ID fijo."
confirm "¿Proyecto dev creado y visible en la consola?"

stage "Auth por correo — dev"
say "Único proveedor que usa esta app: Email/Password."
open_url "https://console.firebase.google.com/project/_/authentication/providers"
note "Si la URL no redirige sola, entra al proyecto dev → Authentication → Sign-in method."
step "Activa 'Email/Password' (sin 'Email link') y guarda."
confirm "¿Email/Password habilitado en dev?"

stage "Plan Blaze + presupuesto — dev"
say "Cloud Functions no despliega en el plan Spark (gratuito) — Blaze es obligatorio, aunque el gasto real caiga en la cuota gratuita."
open_url "https://console.firebase.google.com/project/_/usage/details"
step "Modify plan → Blaze → vincula una cuenta de facturación."
open_url "https://console.cloud.google.com/billing/budgets"
step "Create budget → alcance: proyecto dev → monto USD 5/mes → alertas 50/90/100% → correo orgcolesmanis@gmail.com."
confirm "¿Blaze activo y presupuesto de USD 5/mes creado en dev?"

stage "Service account — dev"
say "Genera la clave que CI usa para desplegar. El archivo baja a tu disco: nunca lo pegues en un chat, sólo dame la ruta."
open_url "https://console.firebase.google.com/project/_/settings/serviceaccounts/adminsdk"
step "Generate new private key → confirma la descarga."
ask FIREBASE_SA_PATH_DEV "Ruta local al .json descargado:"
FIREBASE_SA_JSON_DEV=$(cat "$FIREBASE_SA_PATH_DEV")
set_secret FIREBASE_SERVICE_ACCOUNT_DEV "$FIREBASE_SA_JSON_DEV"
if confirm "¿El secret quedó guardado (revisa el mensaje de arriba)? Si sí, borro el .json local ahora."; then
  rm -f "$FIREBASE_SA_PATH_DEV"
  note "archivo local borrado: $FIREBASE_SA_PATH_DEV"
else
  warn "recuerda borrar $FIREBASE_SA_PATH_DEV a mano — no debe quedar en disco"
fi

stage "Config web — dev (apps/web/.env.dev)"
ENV_FILE="apps/web/.env.dev"
say "Estos 6 valores no son secretos (van en el bundle del cliente), pero cambian por entorno — por eso a un .env y no al código."
open_url "https://console.firebase.google.com/project/_/settings/general"
step "Tus apps → si no hay app web, '</> Add app' → copia los valores de firebaseConfig."
ask VITE_FIREBASE_API_KEY "apiKey:"
ask VITE_FIREBASE_AUTH_DOMAIN "authDomain:"
ask VITE_FIREBASE_PROJECT_ID "projectId:"
ask VITE_FIREBASE_STORAGE_BUCKET "storageBucket:"
ask VITE_FIREBASE_MESSAGING_SENDER_ID "messagingSenderId:"
ask VITE_FIREBASE_APP_ID "appId:"
write_env VITE_FIREBASE_API_KEY "$VITE_FIREBASE_API_KEY"
write_env VITE_FIREBASE_AUTH_DOMAIN "$VITE_FIREBASE_AUTH_DOMAIN"
write_env VITE_FIREBASE_PROJECT_ID "$VITE_FIREBASE_PROJECT_ID"
write_env VITE_FIREBASE_STORAGE_BUCKET "$VITE_FIREBASE_STORAGE_BUCKET"
write_env VITE_FIREBASE_MESSAGING_SENDER_ID "$VITE_FIREBASE_MESSAGING_SENDER_ID"
write_env VITE_FIREBASE_APP_ID "$VITE_FIREBASE_APP_ID"

# ── Prod ────────────────────────────────────────────────────────────────

stage "Proyecto Firebase — prod"
say "Si el proyecto de prod ya existe, sólo confirma para seguir."
open_url "https://console.firebase.google.com/"
step "Add project → nombre sugerido 'Sistema inventario prod' → Analytics opcional (recomendado: activarlo, lo usa la observabilidad del cliente)."
confirm "¿Proyecto prod creado y visible en la consola?"

stage "Auth por correo — prod"
open_url "https://console.firebase.google.com/project/_/authentication/providers"
note "Entra al proyecto prod → Authentication → Sign-in method."
step "Activa 'Email/Password' (sin 'Email link') y guarda."
confirm "¿Email/Password habilitado en prod?"

stage "Plan Blaze + presupuesto — prod"
open_url "https://console.firebase.google.com/project/_/usage/details"
step "Modify plan → Blaze → vincula una cuenta de facturación (puede ser la misma de dev)."
open_url "https://console.cloud.google.com/billing/budgets"
step "Create budget → alcance: proyecto prod → monto USD 10/mes → alertas 50/90/100% → correo orgcolesmanis@gmail.com."
confirm "¿Blaze activo y presupuesto de USD 10/mes creado en prod?"

stage "Service account — prod"
say "Misma idea que en dev: el archivo baja a tu disco, nunca lo pegues en un chat."
open_url "https://console.firebase.google.com/project/_/settings/serviceaccounts/adminsdk"
step "Generate new private key → confirma la descarga."
ask FIREBASE_SA_PATH_PROD "Ruta local al .json descargado:"
FIREBASE_SA_JSON_PROD=$(cat "$FIREBASE_SA_PATH_PROD")
set_secret FIREBASE_SERVICE_ACCOUNT_PROD "$FIREBASE_SA_JSON_PROD"
if confirm "¿El secret quedó guardado (revisa el mensaje de arriba)? Si sí, borro el .json local ahora."; then
  rm -f "$FIREBASE_SA_PATH_PROD"
  note "archivo local borrado: $FIREBASE_SA_PATH_PROD"
else
  warn "recuerda borrar $FIREBASE_SA_PATH_PROD a mano — no debe quedar en disco"
fi

stage "Config web — prod (apps/web/.env.prod)"
ENV_FILE="apps/web/.env.prod"
open_url "https://console.firebase.google.com/project/_/settings/general"
step "Tus apps → si no hay app web, '</> Add app' → copia los valores de firebaseConfig."
ask VITE_FIREBASE_API_KEY "apiKey:"
ask VITE_FIREBASE_AUTH_DOMAIN "authDomain:"
ask VITE_FIREBASE_PROJECT_ID "projectId:"
ask VITE_FIREBASE_STORAGE_BUCKET "storageBucket:"
ask VITE_FIREBASE_MESSAGING_SENDER_ID "messagingSenderId:"
ask VITE_FIREBASE_APP_ID "appId:"
write_env VITE_FIREBASE_API_KEY "$VITE_FIREBASE_API_KEY"
write_env VITE_FIREBASE_AUTH_DOMAIN "$VITE_FIREBASE_AUTH_DOMAIN"
write_env VITE_FIREBASE_PROJECT_ID "$VITE_FIREBASE_PROJECT_ID"
write_env VITE_FIREBASE_STORAGE_BUCKET "$VITE_FIREBASE_STORAGE_BUCKET"
write_env VITE_FIREBASE_MESSAGING_SENDER_ID "$VITE_FIREBASE_MESSAGING_SENDER_ID"
write_env VITE_FIREBASE_APP_ID "$VITE_FIREBASE_APP_ID"

finish
note "Falta manual: crear apps/web/.env.dev.example y .env.prod.example (bloqueado para mí por permisos — ver mensaje del chat)."
